53	/** formatDateTime(time, 'pattern')
54	  * Performs formatting of time, according to provided pattern.
55	  *
56	  * This function is optimized with an assumption, that the resulting strings are fixed width.
57	  * (This assumption is fulfilled for currently supported formatting options).
58	  *
59	  * It is implemented in two steps.
60	  * At first step, it creates a pattern of zeros, literal characters, whitespaces, etc.
61	  *  and quickly fills resulting character array (string column) with this pattern.
62	  * At second step, it walks across the resulting character array and modifies/replaces specific characters,
63	  *  by calling some functions by pointers and shifting cursor by specified amount.
64	  *
65	  * Advantages:
66	  * - memcpy is mostly unrolled;
67	  * - low number of arithmetic ops due to pre-filled pattern;
68	  * - for somewhat reason, function by pointer call is faster than switch/case.
69	  *
70	  * Possible further optimization options:
71	  * - slightly interleave first and second step for better cache locality
72	  *   (but it has no sense when character array fits in L1d cache);
73	  * - avoid indirect function calls and inline functions with JIT compilation.
74	  *
75	  * Performance on Intel(R) Core(TM) i7-6700 CPU @ 3.40GHz:
76	  *
77	  * WITH formatDateTime(now() + number, '%H:%M:%S') AS x SELECT count() FROM system.numbers WHERE NOT ignore(x);
78	  * - 97 million rows per second per core;
79	  *
80	  * WITH formatDateTime(toDateTime('2018-01-01 00:00:00') + number, '%F %T') AS x SELECT count() FROM system.numbers WHERE NOT ignore(x)
81	  * - 71 million rows per second per core;
82	  *
83	  * select count() from (select formatDateTime(t, '%m/%d/%Y %H:%M:%S') from (select toDateTime('2018-01-01 00:00:00')+number as t from numbers(100000000)));
84	  * - 53 million rows per second per core;
85	  *
86	  * select count() from (select formatDateTime(t, 'Hello %Y World') from (select toDateTime('2018-01-01 00:00:00')+number as t from numbers(100000000)));
87	  * - 138 million rows per second per core;
88	  *
89	  * PS. We can make this function to return FixedString. Currently it returns String.
90	  */
91	template <typename Name, bool support_integer>
92	class FunctionFormatDateTimeImpl : public IFunction
