406	    template <typename DataType>
407	    ColumnPtr executeType(const ColumnsWithTypeAndName & arguments, const DataTypePtr &) const
408	    {
409	        auto * times = checkAndGetColumn<typename DataType::ColumnType>(arguments[0].column.get());
410	        if (!times)
411	            return nullptr;
412	
413	        const ColumnConst * pattern_column = checkAndGetColumnConst<ColumnString>(arguments[1].column.get());
414	        if (!pattern_column)
415	            throw Exception("Illegal column " + arguments[1].column->getName()
416	                            + " of second ('format') argument of function " + getName()
417	                            + ". Must be constant string.",
418	                            ErrorCodes::ILLEGAL_COLUMN);
419	
420	        String pattern = pattern_column->getValue<String>();
421	
422	        using T = typename ActionValueTypeMap<DataType>::ActionValueType;
423	        std::vector<Action<T>> instructions;
424	        String pattern_to_fill = parsePattern(pattern, instructions);
425	        size_t result_size = pattern_to_fill.size();
426	
427	        const DateLUTImpl * time_zone_tmp = nullptr;
428	        if (castType(arguments[0].type.get(), [&]([[maybe_unused]] const auto & type) { return true; }))
429	        {
430	            time_zone_tmp = &extractTimeZoneFromFunctionArguments(arguments, 2, 0);
431	        }
432	        else if (std::is_same_v<DataType, DataTypeDateTime64> || std::is_same_v<DataType, DataTypeDateTime>)
433	            time_zone_tmp = &extractTimeZoneFromFunctionArguments(arguments, 2, 0);
434	        else
435	            time_zone_tmp = &DateLUT::instance();
436	
437	        const DateLUTImpl & time_zone = *time_zone_tmp;
438	        const auto & vec = times->getData();
439	
440	        UInt32 scale [[maybe_unused]] = 0;
441	        if constexpr (std::is_same_v<DataType, DataTypeDateTime64>)
442	        {
443	            scale = times->getScale();
444	        }
445	
446	        auto col_res = ColumnString::create();
447	        auto & dst_data = col_res->getChars();
448	        auto & dst_offsets = col_res->getOffsets();
449	        dst_data.resize(vec.size() * (result_size + 1));
450	        dst_offsets.resize(vec.size());
451	
452	        /// Fill result with literals.
453	        {
454	            UInt8 * begin = dst_data.data();
455	            UInt8 * end = begin + dst_data.size();
456	            UInt8 * pos = begin;
457	
458	            if (pos < end)
459	            {
460	                memcpy(pos, pattern_to_fill.data(), result_size + 1);   /// With zero terminator.
461	                pos += result_size + 1;
462	            }
463	
464	            /// Fill by copying exponential growing ranges.
465	            while (pos < end)
466	            {
467	                size_t bytes_to_copy = std::min(pos - begin, end - pos);
468	                memcpy(pos, begin, bytes_to_copy);
469	                pos += bytes_to_copy;
470	            }
471	        }
472	
473	        auto * begin = reinterpret_cast<char *>(dst_data.data());
474	        auto * pos = begin;
475	
476	        for (size_t i = 0; i < vec.size(); ++i)
477	        {
478	            if constexpr (std::is_same_v<DataType, DataTypeDateTime64>)
479	            {
480	                for (auto & instruction : instructions)
481	                {
482	                    const auto c = DecimalUtils::split(vec[i], scale);
483	                    instruction.perform(pos, static_cast<Int64>(c.whole), time_zone);
484	                }
485	            }
486	            else
487	            {
488	                for (auto & instruction : instructions)
489	                    instruction.perform(pos, vec[i], time_zone);
490	            }
491	
492	            dst_offsets[i] = pos - begin;
493	        }
494	
495	        dst_data.resize(pos - begin);
496	        return col_res;
497	    }
