499	    template <typename T>
500	    String parsePattern(const String & pattern, std::vector<Action<T>> & instructions) const
501	    {
502	        String result;
503	
504	        const char * pos = pattern.data();
505	        const char * end = pos + pattern.size();
506	
507	        /// Add shift to previous action; or if there were none, add noop action with shift.
508	        auto add_shift = [&](size_t amount)
509	        {
510	            if (instructions.empty())
511	                instructions.emplace_back(&Action<T>::noop);
512	            instructions.back().shift += amount;
513	        };
514	
515	        /// If the argument was DateTime, add instruction for printing. If it was date, just shift (the buffer is pre-filled with default values).
516	        auto add_instruction_or_shift = [&](typename Action<T>::Func func [[maybe_unused]], size_t shift)
517	        {
518	            if constexpr (std::is_same_v<T, UInt32>)
519	                instructions.emplace_back(func, shift);
520	            else if constexpr (std::is_same_v<T, Int64>)
521	                instructions.emplace_back(func, shift);
522	            else
523	                add_shift(shift);
524	        };
525	
526	        while (true)
527	        {
528	            const char * percent_pos = find_first_symbols<'%'>(pos, end);
529	
530	            if (percent_pos < end)
531	            {
532	                if (pos < percent_pos)
533	                {
534	                    result.append(pos, percent_pos);
535	                    add_shift(percent_pos - pos);
536	                }
537	
538	                pos = percent_pos + 1;
539	
540	                if (pos >= end)
541	                    throw Exception("Sign '%' is the last in pattern, if you need it, use '%%'", ErrorCodes::BAD_ARGUMENTS);
542	
543	                switch (*pos)
544	                {
545	                    // Year, divided by 100, zero-padded
546	                    case 'C':
547	                        instructions.emplace_back(&Action<T>::century, 2);
548	                        result.append("00");
549	                        break;
550	
551	                    // Day of month, zero-padded (01-31)
552	                    case 'd':
553	                        instructions.emplace_back(&Action<T>::dayOfMonth, 2);
554	                        result.append("00");
555	                        break;
556	
557	                    // Short MM/DD/YY date, equivalent to %m/%d/%y
558	                    case 'D':
559	                        instructions.emplace_back(&Action<T>::americanDate, 8);
560	                        result.append("00/00/00");
561	                        break;
562	
563	                    // Day of month, space-padded ( 1-31)  23
564	                    case 'e':
565	                        instructions.emplace_back(&Action<T>::dayOfMonthSpacePadded, 2);
566	                        result.append(" 0");
567	                        break;
568	
569	                    // Short YYYY-MM-DD date, equivalent to %Y-%m-%d   2001-08-23
570	                    case 'F':
571	                        instructions.emplace_back(&Action<T>::ISO8601Date, 10);
572	                        result.append("0000-00-00");
573	                        break;
574	
575	                    // Last two digits of year of ISO 8601 week number (see %G)
576	                    case 'g':
577	                      instructions.emplace_back(&Action<T>::ISO8601Year2, 2);
578	                      result.append("00");
579	                      break;
580	
581	                    // Year of ISO 8601 week number (see %V)
582	                    case 'G':
583	                      instructions.emplace_back(&Action<T>::ISO8601Year4, 4);
584	                      result.append("0000");
585	                      break;
586	
587	                    // Day of the year (001-366)   235
